package java.util;
public class Timer {private boolean cancelled;public Timer(){}public Timer(boolean daemon){}public Timer(String name){if(name==null)throw new NullPointerException();}public Timer(String name,boolean daemon){this(name);}private void start(TimerTask task,long when){if(cancelled)throw new IllegalStateException();task.schedule(when);new Thread(task).start();}public void schedule(TimerTask task,long delay){if(delay<0)throw new IllegalArgumentException();start(task,System.currentTimeMillis()+delay);}public void schedule(TimerTask task,Date time){if(time.getTime()<0)throw new IllegalArgumentException();start(task,time.getTime());}public void schedule(TimerTask task,long delay,long period){if(period<=0)throw new IllegalArgumentException();schedule(task,delay);}public void schedule(TimerTask task,Date firstTime,long period){if(period<=0)throw new IllegalArgumentException();schedule(task,firstTime);}public void scheduleAtFixedRate(TimerTask task,long delay,long period){schedule(task,delay,period);}public void scheduleAtFixedRate(TimerTask task,Date firstTime,long period){schedule(task,firstTime,period);}public void cancel(){cancelled=true;}public int purge(){return 0;}}
